// Munching Voxels - color only, ANIMATED. Runs INSIDE shadeSurface().
// The 1960s "munching squares" display hack, in 3D: space is cut into voxels and a
// voxel lights up when x XOR y XOR z is below a threshold that sweeps up and down.
// The lit region grows as nested cubes and tetrahedra; the surface shows where
// it cuts them. Two munchers run at once (the second on a mirrored lattice, with
// the dock color's channels rotated), each with a glowing front and a fading trail.
// No displacement: one evaluation per pixel. Integer bit operations (GLSL 4.5).
// In scope: pModel, t. Dock colors: u_col1 = first muncher, u_col2 = background.

float CELLS = 12.0 * max(E, 0.05);   // slider E   // voxels per unit         [4 .. 40]
float SPEED = 0.6 * F;               // slider F   // sweeps per 10 seconds   [0 .. 2]
const int BITS = 5;                  // pattern repeats every 2^BITS voxels    [3 .. 7]
float GRID  = 0.35;                  // darkness of the voxel grid lines        [0 .. 1]

int   MASK = (1 << BITS) - 1;
float N    = float(1 << BITS);

vec3  vp = pModel * CELLS;
ivec3 ic = ivec3(floor(vp));
vec3  fp = fract(vp);

int v1 = (ic.x ^ ic.y ^ ic.z) & MASK;
int v2 = (ic.x ^ (MASK - (ic.y & MASK)) ^ ic.z) & MASK;

// thresholds: triangle waves 0 -> N -> 0, the second half a period behind.
// The +0.3 starts them mid-sweep, so the very first frame already shows the pattern.
float ph = 0.1 * SPEED * t + 0.3;
float T1 = N * (1.0 - abs(1.0 - 2.0 * fract(ph)));
float T2 = N * (1.0 - abs(1.0 - 2.0 * fract(ph + 0.5)));

float lit1   = step(float(v1), T1) * (0.35 + 0.65 * float(v1) / max(T1, 1.0));
float front1 = exp(-0.8 * abs(float(v1) - T1));
float lit2   = step(float(v2), T2) * (0.35 + 0.65 * float(v2) / max(T2, 1.0));
float front2 = exp(-0.8 * abs(float(v2) - T2));

vec3 colB = ubuf.u_col1.zxy;
vec3 col = ubuf.u_col2;
col = mix(col, ubuf.u_col1 * 0.7, lit1 * 0.8);
col = mix(col, colB * 0.7, lit2 * 0.5);
col += ubuf.u_col1 * front1 * 0.9 + colB * front2 * 0.6;

// voxel grid: thin dark lines where the surface crosses a voxel face
vec3 e3 = min(fp, 1.0 - fp);
float gridD = min(e3.x, min(e3.y, e3.z));
col *= 1.0 - GRID * (1.0 - smoothstep(0.0, 0.05, gridD));

textureCol = col;
